input.content:
import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(800)
await page.screenshot({ path: 'screenshots/mobile-title-hi.png' })
await page.evaluate(() => document.getElementById('startBtn').click())
await page.waitForTimeout(300)
await page.evaluate(() => document.getElementById('veilSkip').click())
await page.waitForTimeout(900)
for (let i = 0; i < 4; i += 1) {
  await page.evaluate(() => document.getElementById('nextBtn').click())
  await page.waitForTimeout(450)
}
await page.waitForTimeout(500)
await page.screenshot({ path: 'screenshots/mobile-choices-hi.png' })
await page.screenshot({ path: 'screenshots/mobile-crop.png', clip: { x: 0, y: 320, width: 390, height: 100 } })
await browser.close()
console.log('captured')

