import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`))
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`) })

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(700)
await page.click('#startBtn')
await page.waitForTimeout(300)
await page.evaluate(() => { const s = document.getElementById('veilSkip'); if (s) s.click() })
await page.waitForTimeout(700)

const log = []
let ending = false
for (let step = 0; step < 400 && !ending; step += 1) {
  const state = await page.evaluate(() => {
    const vis = (id) => { const e = document.getElementById(id); return e && !e.hidden && e.offsetParent !== null }
    const choices = [...document.querySelectorAll('.choice')].filter((b) => !b.disabled)
    return {
      mini: vis('minigame'),
      choices: choices.length,
      next: vis('nextBtn'),
      ending: vis('ending'),
      day: document.getElementById('dayLabel').textContent,
      line: document.getElementById('line').textContent.slice(0, 24),
      aff: document.getElementById('affectionValue').textContent,
    }
  })

  if (state.ending) { ending = true; break }

  if (state.mini) {
    // tap when the marker is close to the middle (poll quickly in the page)
    await page.evaluate(async () => {
      const btn = document.getElementById('miniTap')
      const marker = document.getElementById('miniMarker')
      for (let round = 0; round < 3; round += 1) {
        await new Promise((resolve) => {
          const t = setInterval(() => {
            if (btn.textContent.includes('계속')) { clearInterval(t); resolve(); return }
            const x = Math.abs(parseFloat(marker.style.left || '0') - 50)
            if (x < 9) { clearInterval(t); btn.click(); resolve() }
          }, 8)
          setTimeout(() => { clearInterval(t); resolve() }, 3500)
        })
        await new Promise((r) => setTimeout(r, 700))
      }
      if (btn.textContent.includes('계속')) btn.click()
    })
    await page.waitForTimeout(300)
    log.push(`${state.day} minigame aff=${state.aff}`)
    continue
  }

  if (state.choices > 0) {
    await page.click('.choice:not(:disabled)')
    log.push(`${state.day} choice aff=${state.aff}`)
    await page.waitForTimeout(350)
    continue
  }

  if (state.next) {
    await page.click('#nextBtn')
    await page.waitForTimeout(180)
    continue
  }

  await page.waitForTimeout(150)
}

const result = await page.evaluate(() => ({
  endingVisible: !document.getElementById('ending').hidden,
  title: document.getElementById('endingTitle').textContent,
  eyebrow: document.getElementById('endingEyebrow').textContent,
  affection: window.__summerGame.state.affection,
  day: window.__summerGame.state.dayIndex,
  beat: window.__summerGame.state.beatIndex,
  memories: window.__summerGame.state.memories.length,
  save: localStorage.getItem('summer-door-save-v2'),
}))
await page.screenshot({ path: 'screenshots/playthrough-ending.png', fullPage: false })

console.log(JSON.stringify({ result, errors, steps: log.length, last: log.slice(-5) }, null, 2))
await browser.close()

import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`))
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`) })

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'load' })
await page.waitForTimeout(600)
await page.click('#startBtn')
await page.waitForTimeout(250)
await page.evaluate(() => document.getElementById('veilSkip')?.click())
await page.waitForTimeout(700)

const snap = () => page.evaluate(() => {
  const shown = (id) => { const e = document.getElementById(id); return !!e && !e.hidden && getComputedStyle(e).display !== 'none' }
  const state = window.__summerGame.state
  return {
    mini: shown('minigame'), choices: document.querySelectorAll('.choice:not(:disabled)').length,
    next: shown('nextBtn'), ending: !document.getElementById('ending').hidden,
    veil: !document.getElementById('dayVeil').hidden, menu: !document.getElementById('menu').hidden,
    day: state.dayIndex, beat: state.beatIndex, line: document.getElementById('line').textContent.slice(0, 30),
    nextLabel: document.getElementById('nextBtn').textContent.trim(),
    aff: state.affection,
  }
})

let ending = false
let idle = 0
const events = []
for (let step = 0; step < 1200 && !ending; step += 1) {
  const s = await snap()
  if (s.ending) { ending = true; break }
  if (s.veil) { await page.waitForTimeout(250); continue }
  if (s.menu) { await page.evaluate(() => document.getElementById('menuClose').click()); continue }

  if (s.mini) {
    await page.evaluate(async () => {
      const btn = document.getElementById('miniTap')
      const marker = document.getElementById('miniMarker')
      for (let round = 0; round < 3; round += 1) {
        await new Promise((resolve) => {
          const t = setInterval(() => {
            const btnDone = btn.textContent.includes('계속')
            if (btnDone) { clearInterval(t); resolve(); return }
            if (Math.abs(parseFloat(marker.style.left || '0') - 50) < 10) { clearInterval(t); btn.click(); resolve() }
          }, 8)
        })
        await new Promise((r) => setTimeout(r, 750))
      }
      if (btn.textContent.includes('계속')) { btn.click(); }
    })
    events.push(`mini day${s.day} aff${s.aff}`)
    idle = 0
    await page.waitForTimeout(300)
    continue
  }

  if (s.choices > 0) {
    await page.evaluate(() => document.querySelector('.choice:not(:disabled)').click())
    events.push(`choice day${s.day} beat${s.beat} aff${s.aff}`)
    idle = 0
    await page.waitForTimeout(400)
    continue
  }

  if (s.next) {
    await page.evaluate(() => document.getElementById('nextBtn').click())
    idle = 0
    await page.waitForTimeout(160)
    continue
  }

  idle += 1
  if (idle === 25) {
    console.log('STUCK SNAPSHOT', JSON.stringify(await snap(), null, 2))
    await page.screenshot({ path: 'screenshots/stuck.png' })
    break
  }
  await page.waitForTimeout(200)
}

const result = await page.evaluate(() => ({
  endingVisible: !document.getElementById('ending').hidden,
  title: document.getElementById('endingTitle').textContent,
  eyebrow: document.getElementById('endingEyebrow').textContent,
  affection: window.__summerGame.state.affection,
  day: window.__summerGame.state.dayIndex,
  beat: window.__summerGame.state.beatIndex,
  memories: window.__summerGame.state.memories.length,
  save: localStorage.getItem('summer-door-save-v2'),
}))
await page.screenshot({ path: 'screenshots/playthrough-ending.png' })
console.log(JSON.stringify({ result, errors, eventCount: events.length, events: events.slice(-8) }, null, 2))
await browser.close()

