import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.evaluate(() => localStorage.clear())
await page.evaluate(() => window.__summerGame.gotoDay(7, 88))
await page.waitForTimeout(700)

for (let i = 0; i < 80; i += 1) {
  const s = await page.evaluate(() => ({
    choices: document.querySelectorAll('.choice').length,
    next: !document.getElementById('nextBtn').hidden,
    ending: !document.getElementById('ending').hidden,
    prompt: document.querySelector('.choice-prompt')?.textContent || '',
  }))
  if (s.ending) break
  if (s.choices) {
    if (s.prompt.includes('마지막')) {
      await page.evaluate(() => document.querySelectorAll('.choice')[1].click())
      await page.waitForTimeout(350)
      break
    }
    await page.evaluate(() => document.querySelectorAll('.choice')[0].click())
    await page.waitForTimeout(300)
    continue
  }
  if (s.next) { await page.evaluate(() => document.getElementById('nextBtn').click()); await page.waitForTimeout(160) }
  else await page.waitForTimeout(120)
}
const save = await page.evaluate(() => JSON.parse(localStorage.getItem('summer-door-save-v2') || 'null'))
console.log('save after final choice', save)
await page.click('#menuBtn')
await page.waitForTimeout(200)
await page.click('#menuTitleBtn')
await page.waitForTimeout(700)
console.log('title', await page.evaluate(() => ({
  screen: document.body.dataset.screen,
  continueHidden: document.getElementById('continueBtn').hidden,
  label: document.getElementById('continueBtn').textContent,
})))
await page.screenshot({ path: 'screenshots/title-ending-continue.png' })
await page.click('#continueBtn')
await page.waitForTimeout(1500)
console.log('continued', await page.evaluate(() => ({
  ending: !document.getElementById('ending').hidden,
  title: document.getElementById('endingTitle').textContent,
  aff: window.__summerGame.state.affection,
  save: localStorage.getItem('summer-door-save-v2'),
})))
await page.screenshot({ path: 'screenshots/ending-from-continue.png' })
console.log('errors', errors)
await browser.close()

