import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
const sizes = [[1440,900],[1024,768],[768,1024],[390,844],[375,667],[360,640],[320,568],[844,390],[667,375]]
const errors=[]
for (const [w,h] of sizes) {
  const page = await browser.newPage({ viewport: { width: w, height: h } })
  page.on('pageerror',e=>errors.push(`${w}x${h} ${e.message}`))
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.evaluate(() => localStorage.clear())
  await page.reload({ waitUntil: 'load' })
  await page.waitForTimeout(500)
  const title = await page.evaluate(() => ({sw:document.documentElement.scrollWidth, iw:innerWidth, sh:document.documentElement.scrollHeight, ih:innerHeight}))
  await page.evaluate(() => window.__summerGame.gotoDay(1, 15))
  await page.waitForTimeout(900)
  const play = await page.evaluate(() => ({sw:document.documentElement.scrollWidth, iw:innerWidth, sh:document.documentElement.scrollHeight, ih:innerHeight}))
  for (let i=0;i<10;i++) {
    if (await page.evaluate(() => document.querySelectorAll('.choice').length)) break
    await page.evaluate(() => document.getElementById('nextBtn').click())
    await page.waitForTimeout(160)
  }
  await page.waitForTimeout(500)
  const choice = await page.evaluate(() => ({sw:document.documentElement.scrollWidth, iw:innerWidth, sh:document.documentElement.scrollHeight, ih:innerHeight, count:document.querySelectorAll('.choice').length}))
  console.log(`${w}x${h}`, JSON.stringify({title, play, choice}))
  await page.close()
}
console.log('errors', errors)
await browser.close()
EOF
